import { Analytics } from '@vercel/analytics/next'
import type { Metadata, Viewport } from 'next'
import { Geist, Geist_Mono } from 'next/font/google'
import localFont from 'next/font/local'
import './globals.css'

const geistSans = Geist({ subsets: ['latin'], variable: '--font-geist-sans' })
const geistMono = Geist_Mono({ subsets: ['latin'], variable: '--font-geist-mono' })
// The NES glyph tiles from Zelda II, generated by
// scripts/generate-zelda2-font.py.
const pixelFont = localFont({
  src: [
    { path: '../public/fonts/zelda2.woff2', style: 'normal', weight: '400' },
    { path: '../public/fonts/zelda2.woff', style: 'normal', weight: '400' },
  ],
  variable: '--font-pixel',
  // The tracker is the only consumer, so no fallback metrics juggling needed.
  adjustFontFallback: false,
  fallback: ['monospace'],
})

export const metadata: Metadata = {
  title: 'Zelda II Randomizer Tracker',
  description: 'An 800 by 600 canvas for a Zelda II randomizer tracker.',
  generator: 'v0.app',
}

export const viewport: Viewport = {
  colorScheme: 'dark',
  themeColor: '#000000',
  width: 'device-width',
  initialScale: 1,
}

export default function RootLayout({ children }: Readonly<{ children: React.ReactNode }>) {
  return (
    <html lang="en" className="bg-background">
      <body className={`${geistSans.variable} ${geistMono.variable} ${pixelFont.variable} font-sans antialiased`}>
        {children}
        {process.env.NODE_ENV === 'production' && <Analytics />}
      </body>
    </html>
  )
}
